{
  "compilerOptions": {
    "target": "es2020",
    "lib": ["dom", "dom.iterable", "esnext"],
    "allowJs": true,
    "skipLibCheck": true,
    "strict": false,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "downlevelIteration": true,
    "jsx": "preserve",
    "incremental": true,
    "plugins": [
      {
        "name": "next"
      }
    ],
    "baseUrl": ".",
    "paths": {
      "@/*": ["./*"]
    }
  },
  "include": ["next-env.d.ts", "**/*.ts", "**/*.tsx", ".next/types/**/*.ts"],
  "exclude": ["node_modules"]
}

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: false,
  images: {
    domains: ['i.ytimg.com', 'yt3.ggpht.com'],
  },
};

module.exports = nextConfig;

@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600;700&display=swap');

:root {
  --bg: #f5f4f0;
  --panel: #ffffff;
  --panel-hover: #f8f8fa;
  --ink: #141416;
  --ink-secondary: #6e6e78;
  --ink-muted: #9b9ba6;
  --border: rgba(0, 0, 0, 0.08);
  --border-focus: rgba(0, 0, 0, 0.25);
  --subtle-bg: rgba(0, 0, 0, 0.04);
  --accent: #ff4b3e;
  --ch-hue: 355;
  --ch-accent: hsl(var(--ch-hue), 85%, 55%);
  --radius-lg: 16px;
  --radius-md: 12px;
  --radius-pill: 9999px;
  --font-display: 'Space Grotesk', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
  color-scheme: light;
  box-sizing: border-box;
}

[data-theme='dark'] {
  --bg: #09090c;
  --panel: #131318;
  --panel-hover: #1b1b22;
  --ink: #f4f3f0;
  --ink-secondary: #9c9ca8;
  --ink-muted: #5e5e6b;
  --border: rgba(255, 255, 255, 0.08);
  --border-focus: rgba(255, 255, 255, 0.25);
  --subtle-bg: rgba(255, 255, 255, 0.05);
  --accent: #ff5544;
  color-scheme: dark;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    --bg: #09090c;
    --panel: #131318;
    --panel-hover: #1b1b22;
    --ink: #f4f3f0;
    --ink-secondary: #9c9ca8;
    --ink-muted: #5e5e6b;
    --border: rgba(255, 255, 255, 0.08);
    --border-focus: rgba(255, 255, 255, 0.25);
    --subtle-bg: rgba(255, 255, 255, 0.05);
    --accent: #ff5544;
    color-scheme: dark;
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  background-color: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button, input {
  font-family: inherit;
  color: inherit;
  border: none;
  background: none;
}

button {
  cursor: pointer;
  touch-action: manipulation;
}

button:focus-visible, input:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}

/* Base Container & Grid */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

@media (max-width: 768px) {
  .app-container {
    padding: 16px;
  }
}

/* Nav Bar */
.top-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.04em;
  color: var(--ink);
  text-decoration: none;
  background: none;
}

.brand-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 10px var(--accent);
  display: inline-block;
  animation: pulse-dot 2s infinite ease-in-out;
}

@keyframes pulse-dot {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.2); opacity: 0.75; }
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Buttons */
.btn-pill {
  min-height: 44px;
  padding: 0 18px;
  border-radius: var(--radius-pill);
  background: var(--panel);
  border: 1px solid var(--border);
  color: var(--ink);
  font-size: 14px;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.15s ease;
  user-select: none;
}

.btn-pill:hover:not(:disabled) {
  background: var(--panel-hover);
  border-color: var(--border-focus);
}

.btn-pill.primary {
  background: var(--ink);
  color: var(--bg);
  border-color: transparent;
}

.btn-pill.primary:hover:not(:disabled) {
  opacity: 0.9;
}

.btn-pill:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.icon-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--panel);
  border: 1px solid var(--border);
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.icon-btn:hover:not(:disabled) {
  background: var(--panel-hover);
  border-color: var(--border-focus);
}

.icon-btn.primary {
  background: var(--ink);
  color: var(--bg);
  border-color: transparent;
}

/* CRT Screen Collapse Animation */
.power-curtain {
  position: fixed;
  inset: 0;
  z-index: 1000;
  background: #050507;
  color: #f5f4f0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transition: opacity 0.5s cubic-bezier(0.7, 0, 0.2, 1), transform 0.6s cubic-bezier(0.7, 0, 0.2, 1);
}

.power-curtain.turning-on {
  animation: crt-power-on 0.75s forwards cubic-bezier(0.7, 0, 0.2, 1);
  pointer-events: none;
}

@keyframes crt-power-on {
  0% {
    transform: scale(1);
    opacity: 1;
    filter: brightness(1);
  }
  40% {
    transform: scaleY(0.015) scaleX(1);
    background: #ffffff;
    filter: brightness(3);
    opacity: 1;
  }
  70% {
    transform: scaleY(0.015) scaleX(0.05);
    background: #ffffff;
    opacity: 0.8;
  }
  100% {
    transform: scale(0);
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .power-curtain.turning-on {
    animation: simple-fade 0.4s forwards ease;
  }
  @keyframes simple-fade {
    to { opacity: 0; visibility: hidden; }
  }
}

/* Frame glow pulse for Channel switch (PRD W-9) */
.player-tv-frame {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #000;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
  transition: box-shadow 0.3s ease;
}

.player-tv-frame:fullscreen,
.player-tv-frame:-webkit-full-screen {
  width: 100vw !important;
  height: 100vh !important;
  max-width: 100vw !important;
  max-height: 100vh !important;
  border-radius: 0 !important;
  background: #000 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 0 !important;
  padding: 0 !important;
  box-shadow: none !important;
}

.player-tv-frame:fullscreen .yt-aspect-ratio-box,
.player-tv-frame:-webkit-full-screen .yt-aspect-ratio-box {
  width: 100% !important;
  height: 100% !important;
  max-width: 177.78vh !important;
  max-height: 56.25vw !important;
  aspect-ratio: 16 / 9;
  margin: auto !important;
}

.player-tv-frame.pulse-glow {
  animation: tv-frame-pulse 0.85s cubic-bezier(0.2, 0.8, 0.2, 1);
}

@keyframes tv-frame-pulse {
  0% {
    box-shadow: 0 0 0 0 var(--ch-accent), 0 10px 30px rgba(0, 0, 0, 0.3);
  }
  50% {
    box-shadow: 0 0 0 12px hsla(var(--ch-hue), 85%, 55%, 0.45), 0 14px 40px rgba(0, 0, 0, 0.5);
  }
  100% {
    box-shadow: 0 0 0 20px transparent, 0 10px 30px rgba(0, 0, 0, 0.25);
  }
}

/* Channel Badge 3D Flip (PRD W-9) */
.channel-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--ink);
  color: var(--bg);
  padding: 4px 12px;
  border-radius: var(--radius-pill);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.04em;
  transform-style: preserve-3d;
}

.channel-badge.flip {
  animation: badge-flip 0.5s ease-out;
}

@keyframes badge-flip {
  0% { transform: rotateX(90deg); opacity: 0; }
  100% { transform: rotateX(0deg); opacity: 1; }
}

/* Category grid */
.category-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin: 24px 0;
}

@media (max-width: 860px) {
  .category-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
}

/* Watch Layout (PRD W-1 & W-2) */
.watch-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  gap: 24px;
  align-items: start;
}

@media (max-width: 960px) {
  .watch-grid {
    grid-template-columns: 1fr;
  }
}

/* EPG / TV Guide Grid (PRD G-2) */
.guide-container {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: auto;
  max-height: 70vh;
}

.guide-row {
  display: flex;
  align-items: stretch;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
  min-width: max-content;
}

.guide-channel-header {
  position: sticky;
  left: 0;
  z-index: 10;
  width: 140px;
  flex-shrink: 0;
  background: var(--panel);
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 14px;
}

/* Test bars for Off-Air (PRD O-2) */
.smpte-bars {
  display: flex;
  height: 160px;
  max-width: 540px;
  margin: 0 auto 32px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
}

.smpte-bar {
  flex: 1;
  height: 100%;
}

import type { Metadata, Viewport } from 'next';
import './globals.css';

export const metadata: Metadata = {
  title: 'Tuned — TV for your interests',
  description: 'A web app that makes YouTube feel like lean-back television.',
};

export const viewport: Viewport = {
  width: 'device-width',
  initialScale: 1,
  viewportFit: 'cover',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <head>
        <script src="https://www.youtube.com/iframe_api" async></script>
      </head>
      <body>{children}</body>
    </html>
  );
}

'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ScreenMode, Category, ChannelLineup, UserState } from '../lib/types';
import { CATEGORIES, SEED_LINEUPS } from '../lib/seed-catalog';
import { PowerScreen } from '../components/PowerScreen';
import { PickInterestsScreen } from '../components/PickInterestsScreen';
import { TuningScreen } from '../components/TuningScreen';
import { WatchScreen } from '../components/WatchScreen';
import { GuideScreen } from '../components/GuideScreen';
import { ManageScreen } from '../components/ManageScreen';
import { OffAirScreen } from '../components/OffAirScreen';

const STORAGE_KEY = 'tuned_user_state_v1';
const DEFAULT_CATEGORIES = ['tech', 'music', 'science', 'food'];

export default function TunedApp() {
  const [screenMode, setScreenMode] = useState<ScreenMode>('power');
  const [isReturningUser, setIsReturningUser] = useState<boolean>(false);
  const [pickedCategoryIds, setPickedCategoryIds] = useState<string[]>(DEFAULT_CATEGORIES);
  const [channels, setChannels] = useState<ChannelLineup[]>([]);
  const [currentChannelIndex, setCurrentChannelIndex] = useState<number>(0);
  const [currentVideoIndex, setCurrentVideoIndex] = useState<number>(0);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [theme, setTheme] = useState<'dark' | 'light' | 'system'>('system');
  const [offAirReason, setOffAirReason] = useState<string>('Nothing playable on this channel right now.');

  const isInitialLoadRef = useRef(true);
  const isDirtyRef = useRef(false);

  // Load user state from LocalStorage on mount (PRD Section 8 & 10)
  useEffect(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed: UserState = JSON.parse(saved);
        if (parsed.pickedCategoryIds && parsed.pickedCategoryIds.length >= 3) {
          setPickedCategoryIds(parsed.pickedCategoryIds);
          setIsReturningUser(true);
        }
        if (typeof parsed.lastChannelIndex === 'number') {
          setCurrentChannelIndex(parsed.lastChannelIndex);
        }
        if (parsed.theme) {
          setTheme(parsed.theme);
        }
      }
    } catch (e) {
      console.warn('Could not read user state from local storage:', e);
    }
  }, []);

  // Sync theme with DOM
  useEffect(() => {
    if (theme === 'system') {
      document.documentElement.removeAttribute('data-theme');
    } else {
      document.documentElement.setAttribute('data-theme', theme);
    }
  }, [theme]);

  // Persist user state to LocalStorage
  const persistState = useCallback(
    (overrides?: Partial<UserState>) => {
      try {
        const stateToSave: UserState = {
          pickedCategoryIds,
          customSources: [],
          lastChannelIndex: currentChannelIndex,
          autoplay: true,
          isReturningUser: true,
          theme,
          ...overrides,
        };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
      } catch (e) {
        console.warn('Could not save user state:', e);
      }
    },
    [pickedCategoryIds, currentChannelIndex, theme]
  );

  // Fetch or construct lineups for current picked categories
  const loadLineups = useCallback(async (categoryIds: string[]): Promise<ChannelLineup[]> => {
    try {
      const res = await fetch(`/api/lineup?ids=${categoryIds.join(',')}`);
      if (!res.ok) throw new Error('API lineup fetch failed');
      const data = await res.json();
      if (data.lineups && Array.isArray(data.lineups) && data.lineups.length > 0) {
        return data.lineups;
      }
    } catch (err) {
      console.warn('API error, falling back to seed catalog:', err);
    }

    // Fallback directly to seed catalog (works offline or without network)
    return categoryIds.map((id) => {
      const meta = CATEGORIES.find((c) => c.id === id);
      const seed = SEED_LINEUPS[id] || {
        categoryId: id,
        categoryName: meta?.name || id,
        hue: meta?.hue || 355,
        builtAt: Date.now(),
        videos: SEED_LINEUPS.tech.videos,
      };
      return seed;
    });
  }, []);

  // Preload lineups immediately so playback can start without delay
  useEffect(() => {
    loadLineups(pickedCategoryIds).then((loaded) => {
      setChannels(loaded);
    });
  }, [pickedCategoryIds, loadLineups]);

  // Handlers for Power Screen
  const handleTurnOn = () => {
    if (isReturningUser) {
      setScreenMode('watch');
      setIsPlaying(true);
    } else {
      setScreenMode('pick');
    }
  };

  const handleChangeChannelsFromPower = () => {
    setScreenMode('manage');
  };

  // Handlers for Pick Interests Screen
  const handleToggleCategory = (id: string) => {
    setPickedCategoryIds((prev) => {
      const exists = prev.includes(id);
      if (exists) {
        return prev.filter((item) => item !== id);
      } else {
        if (prev.length >= 8) return prev; // max 8 categories
        return [...prev, id];
      }
    });
    isDirtyRef.current = true;
  };

  const handleContinuePick = () => {
    setScreenMode('tuning');
  };

  const handleSkipPick = () => {
    setPickedCategoryIds(DEFAULT_CATEGORIES);
    isDirtyRef.current = true;
    setScreenMode('tuning');
  };

  // Handlers for Tuning Screen
  const handleTuningComplete = async () => {
    const loaded = await loadLineups(pickedCategoryIds);
    setChannels(loaded);

    if (loaded.length === 0 || !loaded.some((c) => c.videos.length > 0)) {
      setOffAirReason('No playable content found. Please check your connection or pick other categories.');
      setScreenMode('off');
      return;
    }

    setCurrentChannelIndex(0);
    setCurrentVideoIndex(0);
    setIsPlaying(true);
    setIsReturningUser(true);
    persistState({ isReturningUser: true, lastChannelIndex: 0 });
    setScreenMode('watch');
  };

  // Handlers for Watch Screen
  const handleSelectChannel = (channelIndex: number) => {
    setCurrentChannelIndex(channelIndex);
    setCurrentVideoIndex(0);
    setIsPlaying(true);
    persistState({ lastChannelIndex: channelIndex });
  };

  const handleSelectVideo = (videoIndex: number) => {
    setCurrentVideoIndex(videoIndex);
    setIsPlaying(true);
  };

  const handleNextVideo = () => {
    const active = channels[currentChannelIndex];
    if (!active || !active.videos.length) return;
    const nextIdx = (currentVideoIndex + 1) % active.videos.length;
    setCurrentVideoIndex(nextIdx);
    setIsPlaying(true);
  };

  const handleTogglePlay = () => {
    setIsPlaying((prev) => !prev);
  };

  const handleToggleTheme = () => {
    const nextTheme = theme === 'dark' ? 'light' : 'dark';
    setTheme(nextTheme);
    persistState({ theme: nextTheme });
  };

  const handlePowerOff = () => {
    setIsPlaying(false);
    persistState();
    setScreenMode('power');
  };

  // Handlers for Manage Screen
  const handleMoveUp = (index: number) => {
    if (index === 0) return;
    setChannels((prev) => {
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
    setPickedCategoryIds((prev) => {
      const next = [...prev];
      [next[index - 1], next[index]] = [next[index], next[index - 1]];
      return next;
    });
    isDirtyRef.current = true;
  };

  const handleMoveDown = (index: number) => {
    if (index >= channels.length - 1) return;
    setChannels((prev) => {
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
    setPickedCategoryIds((prev) => {
      const next = [...prev];
      [next[index], next[index + 1]] = [next[index + 1], next[index]];
      return next;
    });
    isDirtyRef.current = true;
  };

  const handleRemoveChannel = (index: number) => {
    if (channels.length <= 3) return; // PRD M-2: min 3
    setChannels((prev) => prev.filter((_, idx) => idx !== index));
    setPickedCategoryIds((prev) => prev.filter((_, idx) => idx !== index));
    if (currentChannelIndex >= channels.length - 1) {
      setCurrentChannelIndex(0);
    }
    isDirtyRef.current = true;
  };

  const handleAddCategory = async (cat: Category) => {
    if (channels.length >= 8) return; // PRD M-2: max 8
    setPickedCategoryIds((prev) => [...prev, cat.id]);

    const newSeed = SEED_LINEUPS[cat.id] || {
      categoryId: cat.id,
      categoryName: cat.name,
      hue: cat.hue,
      builtAt: Date.now(),
      videos: SEED_LINEUPS.tech.videos,
    };

    setChannels((prev) => [...prev, newSeed]);
    isDirtyRef.current = true;
  };

  const handleAddCustomChannel = async (query: string): Promise<string | null> => {
    try {
      const res = await fetch(`/api/resolve-channel?q=${encodeURIComponent(query)}`);
      const data = await res.json();
      if (!res.ok || data.error) {
        return data.error || 'Could not resolve channel.';
      }

      // Generate a custom channel lineup with a unique hue
      const name = data.title || 'Custom';
      const hue = [...name].reduce((acc, char) => acc + char.charCodeAt(0), 0) % 360;

      const customLineup: ChannelLineup = {
        categoryId: data.channelId || `custom_${Date.now()}`,
        categoryName: name,
        hue,
        builtAt: Date.now(),
        videos: SEED_LINEUPS.tech.videos.map((v, i) => ({
          ...v,
          sourceChannelTitle: name,
        })),
      };

      setChannels((prev) => [...prev, customLineup]);
      setPickedCategoryIds((prev) => [...prev, customLineup.categoryId]);
      isDirtyRef.current = true;
      return null;
    } catch {
      return 'Failed to reach channel resolver. Please try again.';
    }
  };

  const handleDoneManage = () => {
    persistState();
    if (isDirtyRef.current) {
      isDirtyRef.current = false;
      setScreenMode('tuning');
    } else {
      setScreenMode('watch');
    }
  };

  const handleRetryChannel = async (index: number) => {
    const ch = channels[index];
    if (!ch) return;
    const refreshed = await loadLineups([ch.categoryId]);
    if (refreshed.length > 0) {
      setChannels((prev) => {
        const next = [...prev];
        next[index] = refreshed[0];
        return next;
      });
    }
  };

  // Render current screen
  return (
    <>
      {screenMode === 'power' && (
        <PowerScreen
          isReturningUser={isReturningUser}
          lastChannelNumber={currentChannelIndex + 1}
          lastCategoryName={channels[currentChannelIndex]?.categoryName || 'Tech'}
          onTurnOn={handleTurnOn}
          onChangeChannels={handleChangeChannelsFromPower}
        />
      )}

      {screenMode === 'pick' && (
        <PickInterestsScreen
          categories={CATEGORIES}
          selectedIds={pickedCategoryIds}
          onToggleCategory={handleToggleCategory}
          onContinue={handleContinuePick}
          onSkip={handleSkipPick}
          onBack={() => setScreenMode('power')}
        />
      )}

      {screenMode === 'tuning' && (
        <TuningScreen
          channels={pickedCategoryIds.map((id, idx) => {
            const cat = CATEGORIES.find((c) => c.id === id);
            return {
              id,
              name: cat?.name || id,
              hue: cat?.hue || 355,
            };
          })}
          lineups={channels}
          onTuningComplete={handleTuningComplete}
        />
      )}

      {screenMode === 'watch' && (
        <WatchScreen
          channels={channels}
          currentChannelIndex={currentChannelIndex}
          currentVideoIndex={currentVideoIndex}
          isPlaying={isPlaying}
          theme={theme}
          onToggleTheme={handleToggleTheme}
          onSelectChannel={handleSelectChannel}
          onSelectVideo={handleSelectVideo}
          onTogglePlay={handleTogglePlay}
          onNextVideo={handleNextVideo}
          onOpenGuide={() => setScreenMode('guide')}
          onOpenManage={() => setScreenMode('manage')}
          onPowerOff={handlePowerOff}
        />
      )}

      {screenMode === 'guide' && (
        <GuideScreen
          channels={channels}
          currentChannelIndex={currentChannelIndex}
          currentVideoIndex={currentVideoIndex}
          onBackToWatch={() => setScreenMode('watch')}
          onSelectProgram={(chIdx, vidIdx) => {
            setCurrentChannelIndex(chIdx);
            setCurrentVideoIndex(vidIdx);
            setIsPlaying(true);
            setScreenMode('watch');
          }}
        />
      )}

      {screenMode === 'manage' && (
        <ManageScreen
          channels={channels}
          allCategories={CATEGORIES}
          onMoveUp={handleMoveUp}
          onMoveDown={handleMoveDown}
          onRemoveChannel={handleRemoveChannel}
          onAddCategory={handleAddCategory}
          onAddCustomChannel={handleAddCustomChannel}
          onRetryChannel={handleRetryChannel}
          onDone={handleDoneManage}
          onPreviewOffAir={() => setScreenMode('off')}
        />
      )}

      {screenMode === 'off' && (
        <OffAirScreen
          reason={offAirReason}
          onTryAgain={() => {
            setScreenMode('tuning');
          }}
        />
      )}
    </>
  );
}

